    private final List<Record> files = new ArrayList<>();

    public void append(Record r) {
        files.add(r); // no atomicity, no validation
        log.fine(() -> "LAKE append raw " + r.getId());
    }
    public int size() { return files.size(); }
    public List<Record> readAll() { return files; }
}
