package com.bank.platforms.warehouse;

import com.bank.platforms.model.Record;
import java.math.BigDecimal;
import java.util.*;
import java.util.logging.Logger;

// Warehouse: validated, governed, fast SQL on clean modelled data.
public class DataWarehouse {
    private static final Logger log = Logger.getLogger(DataWarehouse.class.getName());
    private final Map<String, Record> table = new LinkedHashMap<>();

    public void load(Record r) {
        if (r.getAmount() == null || r.getAmount().compareTo(BigDecimal.ZERO) <= 0) {
            log.warning(() -> "WAREHOUSE rejected invalid " + r.getId());
            return;
        }
        table.put(r.getId(), r);
    }

    public BigDecimal totalByAccount(String accountId) {
        BigDecimal total = BigDecimal.ZERO;
        for (Record r : table.values()) if (r.getAccountId().equals(accountId)) total = total.add(r.getAmount());
        log.info(() -> "WAREHOUSE fast query total for " + accountId + " = " + total);
        return total;
    }
}
