package com.bank.platforms.lakehouse;

import com.bank.platforms.model.Record;
import java.util.*;
import java.util.logging.Logger;

// Lakehouse: lake storage + transaction log → ACID, merge/upsert, time travel.
public class Lakehouse {
    private static final Logger log = Logger.getLogger(Lakehouse.class.getName());

    // Each committed version is a snapshot (time travel).
    private final List<Map<String, Record>> versions = new ArrayList<>();

    public Lakehouse() { versions.add(new LinkedHashMap<>()); } // version 0 (empty)

    // Atomic commit of a merge/upsert → new version.
    public void mergeUpsert(List<Record> batch) {
        Map<String, Record> next = new LinkedHashMap<>(current());
        for (Record r : batch) next.put(r.getId(), r); // upsert by id
        versions.add(next);
        log.info("LAKEHOUSE committed version " + (versions.size() - 1) + " (" + next.size() + " rows)");
    }

    public Map<String, Record> current() { return versions.get(versions.size() - 1); }

    // Time travel: read an older snapshot.
    public Map<String, Record> asOfVersion(int v) {
        log.info("LAKEHOUSE time-travel read of version " + v);
        return versions.get(v);
    }
}
