package com.bank.platforms;

import com.bank.platforms.lake.DataLake;
import com.bank.platforms.lakehouse.Lakehouse;
import com.bank.platforms.model.Record;
import com.bank.platforms.warehouse.DataWarehouse;
import java.math.BigDecimal;
import java.util.List;
import java.util.logging.Logger;

public class PlatformsDemo {
    private static final Logger log = Logger.getLogger(PlatformsDemo.class.getName());

    public static void main(String[] args) {
        log.info("=== DATA LAKE: cheap raw, no transactions ===");
        DataLake lake = new DataLake();
        lake.append(new Record("R1", "SAV2001", new BigDecimal("1200")));
        lake.append(new Record("R2", "SAV2001", null)); // junk accepted — no validation
        log.info("Lake holds " + lake.size() + " raw records (incl junk)");

        log.info("=== DATA WAREHOUSE: clean, governed, fast SQL ===");
        DataWarehouse wh = new DataWarehouse();
        lake.readAll().forEach(wh::load);               // rejects junk
        wh.totalByAccount("SAV2001");

        log.info("=== LAKEHOUSE: ACID upsert + time travel on lake storage ===");
        Lakehouse lh = new Lakehouse();
        lh.mergeUpsert(List.of(new Record("R1", "SAV2001", new BigDecimal("1200")))); // v1
        lh.mergeUpsert(List.of(new Record("R1", "SAV2001", new BigDecimal("9999")),    // update R1
                               new Record("R3", "CUR3001", new BigDecimal("5000")))); // v2
        log.info("Current R1 amount = " + lh.current().get("R1").getAmount());
        log.info("Time-travel v1 R1 amount = " + lh.asOfVersion(1).get("R1").getAmount());
    }
}
